INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40255, 0, 0, 0, 0, 0, 0, 0, 0, 'Brother Kristoff asked for you to assist us, he is a kind man, and faithful to the light. We could use all the help we could get around here, this bastion is in a state of disrepair, not to mention the threats all around.', 0),
(40426, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh, here we are! This is them, thanks again, this means a lot, here, just as I promised.', 0),
(40427, 0, 0, 0, 0, 0, 0, 0, 0, 'It is done, truly?$B$BWhy, thank you $N, you\'ve saved us a massive headache, and countless lives of this city. We have requisitioned a reward worthy of such feats from the treasury itself.$B$BPlease, take one, it is the least we can do.', 0),
(40456, 0, 0, 0, 0, 0, 0, 0, 0, 'Enjoy, enjoy! I will record your name in our super duper subscriber log!', 0),
(40660, 0, 0, 0, 0, 0, 0, 0, 0, 'Hmm, well, that is not all bad, some fighting will certainly need to be discussed with the Admiral, but otherwise I expected much worse...$B$BHere, take this silver, as trouble for running around the city.', 0),
(40661, 0, 0, 0, 0, 0, 0, 0, 0, 'A rose? Why, isn\'t this something else..$B$BFrom the Sailor Borus?$B$B<The woman would let out a soft snicker, smirking openly.>$B$BI remember the name, and that Kul Tiran man well, I never assumed him such a romantic.', 0),
(40662, 0, 0, 0, 0, 0, 0, 0, 0, '<Sailor Borus would let out a loud, and heavy sigh of relief.>$B$BI can\'t thank you enough for this, so much time spent worrying, at the least I was able to finally do something!$B$BHere, for the cost of the rose, I forgot, and some bit extra for doing this on my behalf.', 0),
(40663, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh, this is the good stuff.$B$BWell, from one sailor to, whatever you are mainlander, thanks a bunch.', 0),
(41138, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh, here we are! This is them, thanks again, this means a lot, here, just as I promised.', 0),
(41139, 0, 0, 0, 0, 0, 0, 0, 0, 'It is done, truly?$B$BWhy, thank you $N, you\'ve saved us a massive headache, and countless lives of this city. We have requisitioned a reward worthy of such feats from the treasury itself.$B$BPlease, take one, it is the least we can do.', 0),
(50315, 0, 0, 0, 0, 0, 0, 0, 0, 'What do you mean no one else knows of us?!', 0),
(80315, 0, 0, 0, 0, 0, 0, 0, 0, 'I can feel the life flowing back into my leaves, $R. That druid really worked some magic with that salve. I wonder what\'s inside? I\'ll study it closely until I find out so that other trees like me don\'t get sick, too!', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40255, 0, 0, 'Hello?', 0),
(40426, 0, 0, 'Be careful, the Runic Constructs are quite powerful, an overchage of magical energy gone rampant!', 0),
(40427, 0, 0, 'The longer Arc\'Tiras remains active, the more danger Stormwind lays within, we cannot have rumors spreading, this must be dealt with.', 0),
(40456, 0, 0, 'Well? Cool, right?', 0),
(40660, 0, 0, 'Any luck finding them all?', 0),
(40661, 0, 0, 'Yes?', 0),
(40662, 0, 0, 'Yes?', 0),
(40663, 0, 0, 'So, you find the port...?$B$BLike the ale.', 0),
(41138, 0, 0, 'Be careful, the Runic Constructs are quite powerful, an overchage of magical energy gone rampant!', 0),
(41139, 0, 0, 'The longer Arc\'Tiras remains active, the more danger Stormwind lays within, we cannot have rumors spreading, this must be dealt with.', 0),
(50315, 0, 0, 'All customers are always welcome!$B$BMany thanks, many thanks, stay INFORMED!', 0),
(80315, 0, 0, 'Please hurry, $R. I don\'t know how much longer my leaves have before they completely fall away.', 0);
