INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(61013, 0, 0, 'All is well, enjoying some ale, the views of southern lasses, and enjoying the weather on dry land. He should know me not to cause trouble in foreign lands.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66467'),
(61015, 0, 0, 'Check in on me? Haha! I ain\'t causing no trouble, that goody-two-shoes Milldough should learn to have some fun. All I am doing is exploring, this place is much different than Boralus after all.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66468'),
(61016, 0, 0, 'Check in on me? What does he think he can control me here, and who are you, some worthless constable?', 12, 0, 0, 1, 0, 0, 0, 0, 'Turtle broadcast text 51697'),
(80900, 0, 0, 'Ahh! Applebough. Of course. Here\'s the balm that will help.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66928'),
(80460, 0, 0, 'My leaves. They fall. Big sad.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66929'),
(80460, 1, 0, 'I feel revitalized! The life is flowing back into my branches. Thank you. This is a kindness that I won\'t soon forget!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66931'),
(80451, 0, 0, 'Thanks again for the help! I will make sure to study these so the same thing cannot happen again!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66728');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9061013, 'The south isn\'t so bad after all. Good ale, and a chance to stretch my weary sea legs from the long journey.\n\nWhat can I do for you, mainlander?', 'The south isn\'t so bad after all. Good ale, and a chance to stretch my weary sea legs from the long journey.\n\nWhat can I do for you, mainlander?', 1, 0);
